// Publish the optimized runtime PNGs generated by sync-icons.ps1.
import {copyFileSync,mkdirSync,readFileSync} from 'node:fs'
import {fileURLToPath} from 'node:url'
import path from 'node:path'
const root=fileURLToPath(new URL('../',import.meta.url))
mkdirSync(path.join(root,'frontend/public/brand'),{recursive:true})
for(const [name,file] of [['night','Night_Wave_2048.png'],['light','White_Wave_2048.png']]){
 const source=path.join(root,'android/app/src/main/res/drawable-nodpi/trudomix_wave_'+name+'.png'),png=readFileSync(source)
 if(png.readUInt32BE(16)!==512||png.readUInt32BE(20)!==512)throw Error('Run sync-icons.ps1 first to generate square 512px runtime PNGs')
 copyFileSync(source,path.join(root,'frontend/public/brand/wave-'+name+'.png'))
}
console.log('Updated original transparent Wave PNGs on web and Android.')
